import { IntlShape } from 'react-intl';
import type { RequireAtLeastOne } from 'type-fest';

import type { Timeframe, TimeframeV2 } from '../../../core/types/time.js';
import { formatTimeframe } from '../../../formatters/timeframe/timeframe-formatter.js';
import {
  _getFromToValues,
  _parseTime,
} from '../../forms-core/time/timeParser.js';
import type { TimeframeSelectorPresetItemProps } from '../Item.js';

export const TIMEFRAME_SELECTOR_PRESETS: Array<
  TimeframeSelectorPresetItemProps['value']
> = [
  {
    from: 'now()-30m',
    to: 'now()',
  },
  {
    from: 'now()-1h',
    to: 'now()',
  },
  {
    from: 'now()-2h',
    to: 'now()',
  },
  {
    from: 'now()-24h',
    to: 'now()',
  },
  {
    from: 'now()-7d',
    to: 'now()',
  },
];

/** Converts given timeframe in to a human-readable string */
export function timeframeToDisplayValue(
  value: Timeframe | null,
  intl: IntlShape,
  placeholder?: string,
): string {
  const timeframe = {
    from: value?.from ?? '',
    to: value?.to ?? 'now()',
  };
  return value ? formatTimeframe(timeframe, intl) : placeholder ?? '';
}

/**
 * Check if the value is outside the min - max range.
 * Returns false if the value is not defined, it the from or to values are undefined, or if min and max are both missing.
 * @internal
 */
export function _isOutsideRange(
  value?:
    | {
        /** Start of the time frame. */
        from?: string;
        /** End of the time frame. */
        to?: string;
      }
    | RequireAtLeastOne<TimeframeV2>
    | null,
  min?: string,
  max?: string,
) {
  if (!value || (!min && !max)) {
    return false;
  }

  const { valueFrom, valueTo } = _getFromToValues(value);

  if (!valueFrom || !valueTo) {
    return false;
  }

  // All parse times here need to use the same _now_ date, to not be subject
  // to millisecond differences during parsing.
  const relativeNow = Date.now();

  const fromIsoDate = _parseTime(valueFrom, relativeNow)?.absoluteDate;
  const toIsoDate = _parseTime(valueTo, relativeNow)?.absoluteDate;
  const from = fromIsoDate ? new Date(fromIsoDate) : null;
  const to = toIsoDate ? new Date(toIsoDate) : null;

  if (!from || !to) {
    return false;
  }

  const minIsoDate = _parseTime(min, relativeNow)?.absoluteDate;
  const maxIsoDate = _parseTime(max, relativeNow)?.absoluteDate;
  const minDate = minIsoDate ? new Date(minIsoDate) : null;
  const maxDate = maxIsoDate ? new Date(maxIsoDate) : null;

  // Min date needs to be larger than from and to in order to be considered
  // outside of the range.
  if (
    minDate &&
    (minDate.getTime() > from.getTime() || minDate.getTime() > to.getTime())
  ) {
    return true;
  }

  // Max date needs to be smaller than from and to in order to be considered
  // outside of the range.
  if (
    maxDate &&
    (maxDate.getTime() < from.getTime() || maxDate.getTime() < to.getTime())
  ) {
    return true;
  }

  return false;
}
